def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if all(grid[r][c] == grid[0][c] and grid[0][c] != bg for r in range(h))]

    def regions(size, separators):
        bounds = [-1] + separators + [size]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]

    rr = regions(h, sep_rows)
    cc = regions(w, sep_cols)
    out = [row[:] for row in grid]

    patterns = []
    for r0, r1 in rr:
        for c0, c1 in cc:
            cells = [(r-r0, c-c0, grid[r][c])
                     for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] != bg]
            if cells:
                patterns.append((r1-r0, c1-c0, cells))

    if not patterns:
        return out

    # Use the populated panel's pattern, copying it into every panel of matching size.
    ph, pw, cells = patterns[0]
    for r0, r1 in rr:
        for c0, c1 in cc:
            if r1-r0 == ph and c1-c0 == pw:
                for dr, dc, color in cells:
                    out[r0+dr][c0+dc] = color
    return out
